{
  "name": "QuTech QWG任意波形发生器模块",
  "name_en": "QuTech QWG Arbitrary Waveform Generator Module",
  "manufacturer": "QuTech",
  "description": "QuTech QWG 是一款面向量子实验的任意波形发生器模块，可输出多通道控制波形、管理波形与序列、支持基于 DIO 的 codeword 触发与校准，常用于量子比特控制和读出实验。",
  "description_en": "The QuTech QWG is an arbitrary waveform generator module for quantum experiments. It outputs multi-channel control waveforms, manages waveform and sequence memory, supports DIO codeword triggering and calibration, and is commonly used for qubit control and readout setups.",
  "tag_hints": [
    "arbitrary waveform generation",
    "quantum control pulses",
    "DIO codeword triggering",
    "sequence programming",
    "waveform memory",
    "SCPI instrument control",
    "qubit control"
  ],
  "actions": [
    {
      "action_name": "auto-JSON_parser",
      "description": "解析 SCPI 返回的 JSON 字符串为 JSON 对象。",
      "description_en": "Parse a JSON string returned by SCPI into a JSON object."
    },
    {
      "action_name": "auto-add_parameters",
      "description": "定义并注册 QWG 的控制参数。",
      "description_en": "Define and register QWG control parameters."
    },
    {
      "action_name": "auto-createWaveformReal",
      "description": "创建实数波形并将数据写入 AWG 波形存储。",
      "description_en": "Create a real waveform and write its data to AWG waveform memory."
    },
    {
      "action_name": "auto-deleteWaveform",
      "description": "删除指定名称的波形。",
      "description_en": "Delete a waveform by name."
    },
    {
      "action_name": "auto-detect_underdrive",
      "description": "检测通道欠驱动或下溢状态并发出警告。",
      "description_en": "Check channel underdrive or underflow status and issue a warning."
    },
    {
      "action_name": "auto-dio_calibrate",
      "description": "校准 DIO 输入信号，用于 codeword 位传输。",
      "description_en": "Calibrate DIO input signals used for codeword bit transfer."
    },
    {
      "action_name": "auto-dio_calibration_rapport",
      "description": "获取最近一次 DIO 校准报告。",
      "description_en": "Get the latest DIO calibration report."
    },
    {
      "action_name": "auto-getErrors",
      "description": "读取并报告仪器错误信息。",
      "description_en": "Retrieve and report instrument error messages."
    },
    {
      "action_name": "auto-getWaveformDataFloat",
      "description": "读取指定波形的浮点数据。",
      "description_en": "Read floating-point data of a specified waveform."
    },
    {
      "action_name": "auto-getWaveformLength",
      "description": "获取指定波形的长度。",
      "description_en": "Get the length of a specified waveform."
    },
    {
      "action_name": "auto-getWaveformType",
      "description": "获取指定波形的类型。",
      "description_en": "Get the type of a specified waveform."
    },
    {
      "action_name": "auto-loadWaveformOrSequence",
      "description": "从 AWG 文件系统加载波形或序列。",
      "description_en": "Load a waveform or sequence from the AWG file system."
    },
    {
      "action_name": "auto-newWaveformReal",
      "description": "在 AWG 中新建实数波形条目。",
      "description_en": "Create a new real-valued waveform entry in the AWG."
    },
    {
      "action_name": "auto-sendWaveformDataReal",
      "description": "将归一化实数波形数据上传到 AWG 存储器。",
      "description_en": "Upload normalized real-valued waveform data to AWG memory."
    },
    {
      "action_name": "auto-setSeqElemLoopInfiniteOn",
      "description": "将指定序列元素设置为无限循环。",
      "description_en": "Set a specified sequence element to loop infinitely."
    },
    {
      "action_name": "auto-setSeqLength",
      "description": "设置序列长度。",
      "description_en": "Set the sequence length."
    },
    {
      "action_name": "auto-snapshot_base",
      "description": "生成设备当前状态的 JSON 兼容快照。",
      "description_en": "Generate a JSON-compatible snapshot of the current device state."
    },
    {
      "action_name": "auto-start",
      "description": "启动输出并按当前设置使能通道。",
      "description_en": "Start output and enable channels using the current settings."
    },
    {
      "action_name": "auto-stop",
      "description": "停止通道输出并检查错误或溢出。",
      "description_en": "Stop channel output and check for errors or overflow."
    },
    {
      "action_name": "auto-dio_calibration",
      "description": "执行 DIO 校准流程。",
      "description_en": "Run the DIO calibration procedure."
    },
    {
      "action_name": "auto-calibrate_dio_protocol",
      "description": "校准 DIO 协议相关设置。",
      "description_en": "Calibrate DIO protocol-related settings."
    },
    {
      "action_name": "auto-add_parameter",
      "description": "添加单个设备参数定义。",
      "description_en": "Add a single device parameter definition."
    }
  ]
}

